type Shape interface{ Draw() }

// NewShape picks the concrete type at run time and returns the interface,
// so both concrete types stay unexported to this package.
func NewShape(kind string, a float64) (Shape, error) {
    switch kind {
    case "circle":
        return &circle{radius: a}, nil
    case "square":
        return &square{side: a}, nil
    default:
        return nil, fmt.Errorf("shape: unknown kind %q", kind)
    }
}
